SELECT id, organization_id AS organizationId, site_id AS siteId, vehicle_code AS vehicleCode, name, vehicle_type AS vehicleType, mine_number AS mineNumber, license_plate AS licensePlate, brand, model, rated_load_tons AS ratedLoadTons, status, created_at AS createdAt, updated_at AS updatedAt, archived_at AS archivedAt, version FROM mine_vehicle WHERE organization_id = #{organizationId} AND site_id = #{siteId}
AND (vehicle_code ILIKE CONCAT('%', #{keyword}, '%') OR name ILIKE CONCAT('%', #{keyword}, '%') OR mine_number ILIKE CONCAT('%', #{keyword}, '%'))
AND status = #{status} ORDER BY name, id OFFSET #{offset} LIMIT #{limit}

SELECT COUNT(*) FROM mine_vehicle
WHERE organization_id = #{organizationId} AND site_id = #{siteId}

    AND (vehicle_code ILIKE CONCAT('%', #{keyword}, '%')
         OR name ILIKE CONCAT('%', #{keyword}, '%')
         OR mine_number ILIKE CONCAT('%', #{keyword}, '%'))

  AND status = #{status}

SELECT id, organization_id AS organizationId, site_id AS siteId, tag_code AS tagCode, vendor, model, battery_percent AS batteryPercent, battery_observed_at AS batteryObservedAt, status, created_at AS createdAt, updated_at AS updatedAt, archived_at AS archivedAt, version FROM mine_location_tag WHERE organization_id = #{organizationId} AND site_id = #{siteId}
AND (tag_code ILIKE CONCAT('%', #{keyword}, '%') OR vendor ILIKE CONCAT('%', #{keyword}, '%') OR model ILIKE CONCAT('%', #{keyword}, '%'))
AND status = #{status} ORDER BY tag_code, id OFFSET #{offset} LIMIT #{limit}

SELECT COUNT(*) FROM mine_location_tag
WHERE organization_id = #{organizationId} AND site_id = #{siteId}

    AND (tag_code ILIKE CONCAT('%', #{keyword}, '%')
         OR vendor ILIKE CONCAT('%', #{keyword}, '%')
         OR model ILIKE CONCAT('%', #{keyword}, '%'))

  AND status = #{status}

SELECT id, organization_id AS organizationId, site_id AS siteId, system_code AS systemCode, name, coordinate_type AS coordinateType, unit, epsg_code AS epsgCode, unified, min_x AS minX, max_x AS maxX, min_y AS minY, max_y AS maxY, min_z AS minZ, max_z AS maxZ, status, created_at AS createdAt, updated_at AS updatedAt, archived_at AS archivedAt, version FROM mine_coordinate_system WHERE organization_id = #{organizationId} AND site_id = #{siteId}
AND (system_code ILIKE CONCAT('%', #{keyword}, '%') OR name ILIKE CONCAT('%', #{keyword}, '%'))
AND status = #{status} ORDER BY unified DESC, name, id OFFSET #{offset} LIMIT #{limit}

SELECT COUNT(*) FROM mine_coordinate_system
WHERE organization_id = #{organizationId} AND site_id = #{siteId}

    AND (system_code ILIKE CONCAT('%', #{keyword}, '%')
         OR name ILIKE CONCAT('%', #{keyword}, '%'))

  AND status = #{status}

SELECT COUNT(*) FROM mine_coordinate_transform_version
WHERE organization_id = #{organizationId} AND site_id = #{siteId}
  AND status = #{status}
